  "content": "1|import crypto from 'node:crypto';
2|import type { NativeToolDefinition } from '../../../../../core/ai/tools/ToolRegistry';
3|import { listAvailableActionDefinitions } from '../../../../domain/workflow/actions/registry';
4|import { listPackageActionDefinitions } from '../../../../domain/workflow/actions/packageActionRegistry';
5|import { getActionDefinitionWithPackages, resolveCapabilityProviderWithPackages } from '../../../../domain/workflow/actions/actionResolutionWithPackages';
6|import { resolveWorkflowSecretFromEnv } from '../../../../domain/workflow/engine/secretResolution';
7|import type { ActionDefinition, ActionExecutorContext } from '../../../../domain/workflow/actions/types';
8|import type { JsonValue } from '../../../../domain/workflow/awm/types';
9|
10|/**
11| * p-99/WFT-4 — connects the workflow Action catalog (CORE/PLATFORM + package-contributed,
12| * `actionResolutionWithPackages.ts`) directly to the AppEndoo agent's `ToolRegistry`, as TWO
13| * generic tools rather than one tool per action (~74+ and growing) — matching this project's own
14| * "few general tools, not dozens of single-purpose ones" direction (p-98 audit) and avoiding
15| * flooding the agent's tool list every time a new Action ships. This is deliberately NOT a real
16| * MCP server (see the p-99 plan's WFT-4 decision note) — it is an in-process adapter reusing the
17| * same Action Registry the workflow engine dispatches against, with no network protocol involved.
18| *
19| * V1 safety boundary, deliberately narrower than a real workflow's ON_ERROR/saga-backed dispatch:
20| * only `sideEffectClass !== 'WRITE_EXTERNAL'` Actions are invocable here (data transforms, crypto,
21| * text/date, web fetch/search, identity reads, AI calls, read-only DB queries, ...). An Action with
22| * a real external write effect (CMS writes, email sends, ...) is excluded — those still require a
23| * real workflow definition, consistent with this agent's existing draft-then-confirm posture for
24| * anything that writes. `AGENTIC` executionMode actions are excluded too (none exist in the
25| * catalog today, per `types.ts`'s own doc comment on why AGENTIC is unused — excluding by
26| * construction rather than assuming that never changes).
27| */
28|
29|export const LIST_WORKFLOW_ACTIONS_TOOL_NAME = 'list_workflow_actions';
30|export const INVOKE_WORKFLOW_ACTION_TOOL_NAME = 'invoke_workflow_action';
31|
32|const MAX_INVOKE_TIMEOUT_MS = 30_000;
33|
34|export const isActionInvocableFromAgent = (definition: ActionDefinition): boolean => (
35|  definition.availability === 'AVAILABLE'
36|  && definition.executionMode === 'DETERMINISTIC'
37|  && definition.sideEffectClass !== 'WRITE_EXTERNAL'
38|);
39|
40|function listInvocableActionDefinitions(): ActionDefinition[] {
41|  const seen = new Set<string>();
42|  const combined: ActionDefinition[] = [];
43|  for (const definition of [...listAvailableActionDefinitions(), ...listPackageActionDefinitions()]) {
44|    const key = `${definition.key}@${definition.version}`;
45|    if (seen.has(key)) continue; // CORE/PLATFORM wins over a same-key package entry — listed first.
46|    seen.add(key);
47|    combined.push(definition);
48|  }
49|  return combined.filter(isActionInvocableFromAgent);
50|}
51|
52|export const executeListWorkflowActions = (args: Record<string, unknown>) => {
53|  const categoryFilter = typeof args.category === 'string' ? args.category.trim() : '';
54|  const items = listInvocableActionDefinitions()
55|    .filter((definition) => !categoryFilter || definition.key.startsWith(`${categoryFilter}.`))
56|    .map((definition) => ({
57|      key: definition.key,
58|      version: definition.version,
59|      contributor: definition.contributor,
60|      sideEffectClass: definition.sideEffectClass,
61|      riskClass: definition.riskClass,
62|      tags: definition.tags,
63|      configSchema: definition.configSchema,
64|      inputSchema: definition.inputSchema,
65|      outputSchema: definition.outputSchema,
66|    }))
67|    .sort((a, b) => a.key.localeCompare(b.key));
68|
69|  return {
70|    ok: true as const,
71|    summary: `Listed ${items.length} invocable workflow action(s)${categoryFilter ? ` matching "${categoryFilter}.*"` : ''}.`,
72|    data: { items, totalCount: items.length },
73|  };
74|};
75|
76|const syntheticAgentActionContext = (actionKey: string): ActionExecutorContext => ({
77|  workflowInstanceId: 'AGENT_TOOL',
78|  nodeInstanceId: `AGENT_TOOL:${actionKey}`,
79|  logicalInvocationId: `AGENT_TOOL:${actionKey}:${crypto.randomUUID()}`,
80|  idempotencyKey: `AGENT_TOOL:${actionKey}:${crypto.randomUUID()}`,
81|  effectiveIdentity: { type: 'SYSTEM', id: null },
82|  cancellationSignal: new AbortController().signal,
83|  resolveSecret: resolveWorkflowSecretFromEnv,
84|  logger: { info: () => {}, warn: () => {}, error: () => {} },
85|  writeTraceMetadata: () => {},
86|});
87|
88|const asJsonObject = (value: unknown): JsonValue => (
89|  value && typeof value === 'object' && !Array.isArray(value) ? value as JsonValue : {}
90|);
91|
92|export const executeInvokeWorkflowAction = async (args: Record<string, unknown>) => {
93|  const actionKey = typeof args.actionKey === 'string' ? args.actionKey.trim() : '';
94|  const actionVersion = typeof args.actionVersion === 'string' ? args.actionVersion.trim() : '';
95|  if (!actionKey || !actionVersion) {
96|    return { ok: false as const, summary: 'actionKey and actionVersion are required — call list_workflow_actions first to find them.', error: 'missing_action_ref' };
97|  }
98|
99|  const registered = getActionDefinitionWithPackages(actionKey, actionVersion);
100|  if (!registered) {
101|    return { ok: false as const, summary: `Workflow action "${actionKey}@${actionVersion}" was not found.`, error: 'action_not_found' };
102|  }
103|  const { definition } = registered;
104|  if (!isActionInvocableFromAgent(definition)) {
105|    return {
106|      ok: false as const,
107|      summary: `Workflow action "${actionKey}@${actionVersion}" cannot be invoked directly (sideEffectClass=${definition.sideEffectClass}, executionMode=${definition.executionMode}, availability=${definition.availability}). Actions with external write effects need a real workflow definition.`,
108|      error: 'action_not_invocable',
109|    };
110|  }
111|
112|  let executor;
113|  try {
114|    executor = resolveCapabilityProviderWithPackages(actionKey, actionVersion, definition.requiredCapabilities, () => true).winner.executor;
115|  } catch (error) {
116|    return { ok: false as const, summary: `No provider is registered for "${actionKey}@${actionVersion}".`, error: error instanceof Error ? error.message : String(error) };
117|  }
118|
119|  const config = asJsonObject(args.config);
120|  const input = asJsonObject(args.input);
121|  const timeoutMs = Math.min(definition.executionTimeoutMs, MAX_INVOKE_TIMEOUT_MS);
122|
123|  let result;
124|  try {
125|    result = await Promise.race([
126|      executor.execute(syntheticAgentActionContext(actionKey), config, input),
127|      new Promise<never>((_, reject) => setTimeout(() => reject(new Error(`Action "${actionKey}@${actionVersion}" exceeded ${timeoutMs}ms.`)), timeoutMs)),
128|    ]);
129|  } catch (error) {
130|    return { ok: false as const, summary: error instanceof Error ? error.message : String(error), error: 'action_timeout_or_throw' };
131|  }
132|
133|  if (result.status === 'SUCCEEDED') {
134|    return { ok: true as const, summary: `Action "${actionKey}@${actionVersion}" succeeded.`, data: { output: result.output } };
135|  }
136|  return { ok: false as const, summary: `Action "${actionKey}@${actionVersion}" failed: ${result.safeMessage}`, error: result.errorCode };
137|};
138|
139|export const createWorkflowActionsTools = (): NativeToolDefinition[] => [
140|  {
141|    name: LIST_WORKFLOW_ACTIONS_TOOL_NAME,
142|    description: 'List workflow Actions (AppEndO\'s built-in + package-contributed toolbox) invocable via invoke_workflow_action — read-only/computational actions only (data transforms, crypto, text, date, web fetch/search, identity reads, AI calls, read-only DB queries). Actions with external write effects (CMS writes, emails, ...) are excluded; those need a real workflow definition. Optionally filter by a key-prefix category (e.g. "crypto", "identity").',
143|    group: 'workflow',
144|    parameters: {
145|      type: 'object',
146|      properties: {
147|        category: { type: 'string', description: 'Optional key-prefix filter, e.g. "data", "crypto", "identity", "web".' },
148|      },
149|    },
150|    execute: async (args) => executeListWorkflowActions(args),
151|  },
152|  {
153|    name: INVOKE_WORKFLOW_ACTION_TOOL_NAME,
154|    description: 'Invoke one workflow Action by exact key + version, outside of any workflow instance. Call list_workflow_actions first to discover available keys and their config/input JSON Schemas.',
155|    group: 'workflow',
156|    parameters: {
157|      type: 'object',
158|      properties: {
159|        actionKey: { type: 'string', description: 'Exact action key from list_workflow_actions, e.g. "crypto.hash".' },
160|        actionVersion: { type: 'string', description: 'Exact action version from list_workflow_actions, e.g. "1".' },
161|        config: { type: 'object', description: 'Author-time config values, matching the action\'s configSchema.' },
162|        input: { type: 'object', description: 'Per-invocation input values, matching the action\'s inputSchema.' },
163|      },
164|      required: ['actionKey', 'actionVersion'],
165|    },
166|    execute: async (args) => executeInvokeWorkflowAction(args),
167|  },
168|];
169|"
}
